"use client";

import type {
  AppliedReport,
  Decisions,
  DetectedPlan,
  PlanEdits,
  PlanStatus,
} from "../../lib/scan/instrumentation";
import {
  startTransition,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";

import { FlowMap, type MapZoomTarget } from "../scan/flow-map";

import { DecisionList, type EditPatch } from "./decision-list";
import { SetupSummary } from "./setup-summary";
import { VerificationReport } from "./verification-report";

// Hovering a decision row spotlights its subject on the map: a single agent
// by node label, a single workflow by group label.
export type SetupFocus =
  | { type: "agent"; name: string }
  | { type: "workflow"; name: string }
  | null;

/**
 * Review-time overrides, keyed by decision id. Only divergence from the
 * detected values is stored; approving converts whatever remains into the
 * `PlanEdits` patch the server merges (server-side, onto ITS copy — the
 * browser never ships a whole decisions blob).
 */
export interface EditsState {
  agents: Record<string, { name?: string; oneOff?: boolean }>;
  workflows: Record<string, { name?: string; runIdSource?: string }>;
  sessions: Record<string, { label?: string; sessionIdSource?: string }>;
  customer?: { recommended?: boolean; idSource?: string };
}

const NO_EDITS: EditsState = { agents: {}, workflows: {}, sessions: {} };

/** Drop `undefined` fields; return undefined when nothing survives. */
function compact<T extends Record<string, unknown>>(o: T): T | undefined {
  const entries = Object.entries(o).filter(([, v]) => v !== undefined);
  return entries.length ? (Object.fromEntries(entries) as T) : undefined;
}

// The review surface. Shares the map with the public scan board, but nothing
// else: no attribution, no rail, no share affordances — the user is already
// signed in on our own domain, and this page's one job is a decision. A single
// left column carries the summary+actions card and the compact decision list;
// the rest of the viewport belongs to the map.

/** Clearance for the initial map fit: the left column is all there is. */
const MAP_PADDING = { left: 452, right: 48 };

export function SetupBoardBlock({
  plan,
  approved,
  applied,
  status,
  firstTraceId,
  approvedAt,
  agentResumedAt,
  spanCount,
  secondsToFirstTrace,
  failureStage,
  onApprove,
  onReject,
  approving,
}: {
  plan: DetectedPlan;
  /** The decisions actually agreed to (detected + edits), once approved. */
  approved?: Decisions | null;
  /** The agent's after-report, once the plan has been applied. */
  applied?: AppliedReport | null;
  status: PlanStatus;
  firstTraceId?: string | null;
  /** ISO timestamps — tRPC serializes dates to strings on this app. */
  approvedAt?: string | null;
  agentResumedAt?: string | null;
  spanCount?: number | null;
  secondsToFirstTrace?: number | null;
  failureStage?: string | null;
  onApprove: (edits: PlanEdits | undefined) => void;
  onReject: () => void;
  approving: boolean;
}) {
  const [focus, setFocusState] = useState<SetupFocus>(null);
  // Spotlighting re-renders the whole map, so hover commits are debounced:
  // scrolling (or sweeping the pointer down) the list fires mouseenter on
  // every row it passes, and rendering the map once per row is what made the
  // list feel laggy. Only the row the cursor actually RESTS on gets a render
  // — consecutive calls coalesce to the last one. The commit itself is still
  // a transition, so React can abandon it if a newer focus lands mid-render.
  const focusTimer = useRef<number | null>(null);
  const setFocus = useCallback((focus: SetupFocus) => {
    if (focusTimer.current !== null) window.clearTimeout(focusTimer.current);
    focusTimer.current = window.setTimeout(() => {
      focusTimer.current = null;
      startTransition(() => setFocusState(focus));
    }, 90);
  }, []);
  useEffect(
    () => () => {
      if (focusTimer.current !== null) window.clearTimeout(focusTimer.current);
    },
    []
  );
  // Clicking a row flies the map to its subject. A fresh object per click on
  // purpose: re-clicking the same row after panning away re-centers it.
  const [zoom, setZoom] = useState<MapZoomTarget | null>(null);
  const selectFocus = useCallback((focus: NonNullable<SetupFocus>) => {
    setZoom(
      focus.type === "agent"
        ? { labels: [focus.name] }
        : { groups: [focus.name] }
    );
  }, []);

  // Each patch carries the row's WHOLE override (the editor threads untouched
  // fields through), so merging is replacement: compact the patch, then store
  // or delete the row.
  const [edits, setEdits] = useState<EditsState>(NO_EDITS);
  const applyEdit = useCallback((patch: EditPatch) => {
    setEdits((prev) => {
      if (patch.kind === "customer") {
        const row = compact({
          recommended: patch.recommended,
          idSource: patch.idSource,
        });
        return { ...prev, customer: row };
      }
      const { kind, id, ...fields } = patch;
      const key = (
        { agent: "agents", workflow: "workflows", session: "sessions" } as const
      )[kind];
      const rows = { ...prev[key] } as Record<string, object>;
      const row = compact(fields);
      if (row) rows[id] = row;
      else delete rows[id];
      return { ...prev, [key]: rows };
    });
  }, []);

  // The wire shape: arrays of {id, ...changes}. Overrides equal to the
  // detected value were never stored, so everything here is a real change.
  const buildEdits = useCallback((): PlanEdits | undefined => {
    const agents = Object.entries(edits.agents).map(([id, e]) => ({
      id,
      ...e,
    }));
    const workflows = Object.entries(edits.workflows).map(([id, e]) => ({
      id,
      ...e,
    }));
    const sessions = Object.entries(edits.sessions).map(([id, e]) => ({
      id,
      ...e,
    }));
    if (
      !agents.length &&
      !workflows.length &&
      !sessions.length &&
      !edits.customer
    ) {
      return undefined;
    }
    return { agents, workflows, sessions, customer: edits.customer };
  }, [edits]);

  // The one edit that can make approval fail server-side: customer attribution
  // switched on with no id source. Catch it here and disable Approve — the
  // decision row already explains what's missing — instead of letting the
  // click round-trip into a schema-speak error toast.
  const customerOn =
    edits.customer?.recommended ?? plan.decisions.customer.recommended;
  const customerIdSource =
    edits.customer?.idSource ?? plan.decisions.customer.idSource;
  const approveBlocked = customerOn && !customerIdSource;

  // Post-approval the source of truth flips: the list shows what was agreed
  // to (detected + edits), not the raw detection.
  const decisions = approved ?? plan.decisions;
  // Stable identity — FlowMap relayouts when the group-name CONTENT changes.
  // Union of detected and approved names: the before-graph carries detected
  // group labels, the agent's after-graph carries the (possibly renamed)
  // approved ones, and matching is by name.
  const workflowNames = useMemo(() => {
    const names = new Set(plan.decisions.workflows.map((w) => w.name));
    for (const w of approved?.workflows ?? []) names.add(w.name);
    return [...names];
  }, [plan, approved]);
  // Once the agent reports back, the map shows the instrumented architecture.
  const graph = applied?.scan.graph ?? plan.scan.graph;

  return (
    <div className="fixed inset-0 overflow-hidden bg-neutral-100 text-foreground dark:bg-background">
      {/* The one column: what was found + approve, then why. The page never
          scrolls — the decisions card fills whatever height the summary
          leaves and scrolls inside itself. */}
      <div className="absolute top-6 bottom-6 left-6 z-20 flex w-72 flex-col gap-4">
        <SetupSummary
          plan={plan}
          status={status}
          firstTraceId={firstTraceId}
          approvedAt={approvedAt}
          agentResumedAt={agentResumedAt}
          failureStage={failureStage}
          approveBlocked={approveBlocked}
          onApprove={() => onApprove(buildEdits())}
          onReject={onReject}
          approving={approving}
        />
        {applied ? (
          <VerificationReport
            before={plan.scan}
            report={applied}
            verified={status === "verified"}
            spanCount={spanCount}
            secondsToFirstTrace={secondsToFirstTrace}
          />
        ) : null}
        <DecisionList
          decisions={decisions}
          edits={edits}
          editable={status === "awaiting_approval"}
          onEdit={applyEdit}
          onFocus={setFocus}
          onSelect={selectFocus}
        />
      </div>

      <FlowMap
        graph={graph}
        focusKinds={null}
        focusLabels={focus?.type === "agent" ? [focus.name] : null}
        focusGroups={focus?.type === "workflow" ? [focus.name] : null}
        workflowGroups={workflowNames}
        padding={MAP_PADDING}
        zoomTo={zoom}
      />
    </div>
  );
}

/* Original design and implementation by Gustavo Fior (@gustavo-fior), co-founder Abdul Haidar and Foglamp Labs.
 * Extracted from foglamp-labs/foglamp under Apache-2.0.
 */
"use client";

import type {
  DetectedPlan,
  PlanStatus,
} from "../../lib/scan/instrumentation";
import { Button } from "../../ui/button";
import { Card, CardContent } from "../../ui/card";
import { Spinner } from "../../ui/spinner";
import { cn } from "../../lib/utils";
import { IconCheck, IconExclamationCircle } from "@tabler/icons-react";
import { FoglampLink as Link } from "../../lib/link-context";
import { useEffect, useState } from "react";

// The one card that runs the whole show: what Foglamp found, the approve /
// reject actions, and — once the user has clicked — a compact live status line
// in the same spot. Merging these means the page has exactly one place to
// look, and the button row turning into "Agent is applying…" right where the
// user just clicked is the clearest possible feedback that the loop is live.

function plural(n: number, one: string, many = `${one}s`): string {
  return `${n} ${n === 1 ? one : many}`;
}

/** "4 agents, 2 workflows, 1 conversation flow, and 13 model calls" */
function phrase(parts: string[]): string {
  if (parts.length === 0) return "nothing to instrument yet";
  if (parts.length === 1) return parts[0]!;
  return `${parts.slice(0, -1).join(", ")}, and ${parts.at(-1)}`;
}

type Tone = "working" | "done" | "stopped";

// One line each — the headline above already carries the context.
const STATUS_LINE: Record<
  Exclude<PlanStatus, "awaiting_approval">,
  { text: string; tone: Tone }
> = {
  approved: {
    text: "Approved. Just wait for your agent to pick this up.",
    tone: "working",
  },
  applying: { text: "Agent is applying your plan.", tone: "working" },
  applied: {
    text: "Instrumentation is in. Trigger your AI flows and see the first trace.",
    tone: "working",
  },
  verified: { text: "Verified — your first trace landed.", tone: "done" },
  rejected: {
    text: "Rejected. Nothing was changed in your repo.",
    tone: "stopped",
  },
  expired: {
    text: "This plan expired. Run the setup prompt again for a fresh one.",
    tone: "stopped",
  },
  failed: {
    text: "Your agent couldn't finish. Check its output, then run the prompt again.",
    tone: "stopped",
  },
};

// The two "your agent might be gone" thresholds. A live wait loop picks an
// approval up in ~1 second, so a couple of minutes in `approved` means the
// agent almost certainly stopped waiting (its loop gives up after ~30 min).
// Applying is real work, so it gets far more slack before we raise an eyebrow.
const AGENT_GONE_MS = 2 * 60_000;
const APPLY_SLOW_MS = 10 * 60_000;

const TONE_TEXT: Record<Tone, string> = {
  working: "text-muted-foreground",
  done: "text-emerald-600 dark:text-emerald-400",
  stopped: "text-amber-600 dark:text-amber-400",
};

function StatusIcon({ tone }: { tone: Tone }) {
  if (tone === "done")
    return <IconCheck className="size-3.5 shrink-0 mt-0.75" stroke={2.5} />;
  if (tone === "stopped")
    return <IconExclamationCircle className="size-3.5 shrink-0 mt-0.75" />;
  // The shared `Spinner` is an unconditional `animate-spin`, so the reduced-
  // motion opt-out has to be applied here.
  return (
    <Spinner className="size-3.5 shrink-0 motion-reduce:animate-none mt-0.75" />
  );
}

export function SetupSummary({
  plan,
  status,
  firstTraceId,
  approvedAt,
  agentResumedAt,
  failureStage,
  approveBlocked,
  onApprove,
  onReject,
  approving,
}: {
  plan: DetectedPlan;
  status: PlanStatus;
  firstTraceId?: string | null;
  /** ISO timestamps — tRPC serializes dates to strings on this app. */
  approvedAt?: string | null;
  agentResumedAt?: string | null;
  failureStage?: string | null;
  /** A decision is incomplete (customer attribution without an id source). */
  approveBlocked?: boolean;
  onApprove: () => void;
  onReject: () => void;
  approving: boolean;
}) {
  // Rejecting is terminal — the agent exits and the only way back is pasting
  // the whole prompt again — so one stray click next to Approve must not end
  // the session. First click arms, second click fires, a pause disarms.
  const [confirmReject, setConfirmReject] = useState(false);
  useEffect(() => {
    if (!confirmReject) return;
    const t = window.setTimeout(() => setConfirmReject(false), 5_000);
    return () => window.clearTimeout(t);
  }, [confirmReject]);

  // Recomputed on every poll-driven render (the page refetches every couple
  // of seconds while the plan can still move), so these flip on their own.
  const now = Date.now();
  const agentGone =
    status === "approved" &&
    approvedAt != null &&
    now - Date.parse(approvedAt) > AGENT_GONE_MS;
  const applyStartedAt = agentResumedAt ?? approvedAt;
  const applySlow =
    status === "applying" &&
    applyStartedAt != null &&
    now - Date.parse(applyStartedAt) > APPLY_SLOW_MS;
  const parts: string[] = [];
  const { agents, workflows, sessions } = plan.decisions;
  if (agents.length) parts.push(plural(agents.length, "agent"));
  if (workflows.length) parts.push(plural(workflows.length, "workflow"));
  if (sessions.length) parts.push(plural(sessions.length, "conversation flow"));
  if (plan.calls.length) parts.push(plural(plan.calls.length, "model call"));

  return (
    <Card className="rounded-[28px] squircle:rounded-[28px] py-0">
      <CardContent className="px-5 py-4">
        <h1 className="font-display text-[15px] font-semibold tracking-tight">
          Foglamp{" "}
          <span className="font-sans font-normal tracking-normal text-sm">
            found {phrase(parts)}.
          </span>
        </h1>
        {status === "awaiting_approval" ? (
          <>
            <div className="mt-4 flex items-center justify-end gap-2">
              <Button
                size="sm"
                variant={confirmReject ? "destructive" : "secondary"}
                className="flex-1"
                onClick={() => {
                  if (confirmReject) onReject();
                  else setConfirmReject(true);
                }}
                disabled={approving}
              >
                {confirmReject ? "Really reject?" : "Reject"}
              </Button>
              <Button
                size="sm"
                className="flex-1"
                onClick={onApprove}
                disabled={approving || approveBlocked}
              >
                {approving ? "Approving…" : "Approve"}
              </Button>
            </div>
            {approveBlocked ? (
              <p className="mt-2 text-[11px] leading-relaxed text-amber-600 dark:text-amber-400">
                Add a customer id source below — or turn attribution off — to
                approve.
              </p>
            ) : null}
            {confirmReject ? (
              <p className="mt-2 text-[11px] leading-relaxed text-muted-foreground">
                Rejecting stops your agent; nothing in your repo changes.
              </p>
            ) : null}
          </>
        ) : (
          <div className={cn("mt-4")}>
            <div
              className={cn(
                "flex items-start gap-2",
                TONE_TEXT[STATUS_LINE[status].tone]
              )}
            >
              <StatusIcon tone={STATUS_LINE[status].tone} />
              <div className="flex flex-col gap-2">
                <p className="text-xs leading-relaxed">
                  {STATUS_LINE[status].text}
                  {status === "failed" && failureStage
                    ? ` It stopped while trying to ${failureStage} the plan.`
                    : null}
                </p>
              </div>
            </div>
            {agentGone ? (
              <p className="mt-2 text-[11px] leading-relaxed text-amber-600 dark:text-amber-400">
                Still waiting? Your agent probably stopped listening. Send it
                any message — &ldquo;continue&rdquo; works — and it will pick
                this plan up.
              </p>
            ) : null}
            {applySlow ? (
              <p className="mt-2 text-[11px] leading-relaxed text-amber-600 dark:text-amber-400">
                This is taking a while. Check your agent&rsquo;s output — it
                may be stuck or waiting on you.
              </p>
            ) : null}
            {status === "verified" && firstTraceId ? (
              <Button
                size="sm"
                className="w-full mt-4"
                render={
                  <Link
                    href={
                      `/traces/${encodeURIComponent(firstTraceId)}`
                    }
                  />
                }
              >
                View your first trace
              </Button>
            ) : null}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

