"use client";

import type { AppliedReport } from "../../lib/scan/instrumentation";
import type { ScanData } from "../../lib/scan/scan";
import { Card, CardContent } from "../../ui/card";
import { cn } from "../../lib/utils";
import {
  IconAlertTriangleFilled,
  IconCircleCheckFilled,
  IconEditFilled,
  IconFileCodeFilled,
  IconFileDiffFilled,
  IconMinus,
  IconPlusFilled,
} from "@tabler/icons-react";
import { useMemo, useState } from "react";

import { diffScans } from "../../lib/scan/diff";
import { KIND_STYLES } from "../scan/kinds";

// The Stage 3 payoff: once the agent has applied the plan, the review page
// stops being a promise and becomes a receipt. This card renders the agent's
// AppliedReport — instrumentation coverage, what moved on the map (before
// scan vs after scan), which files were touched, and anything the agent
// flagged. Same card anatomy as the decision list: sections inside one
// scrolling content area.

/** Entries shown per foldable list before "Show N more". */
const SHOWN = 4;

function Section({
  label,
  Icon,
  iconClassName,
  children,
}: {
  label: string;
  Icon: React.ComponentType<{ className?: string }>;
  iconClassName?: string;
  children: React.ReactNode;
}) {
  return (
    <section className="mt-5 px-1 first:mt-1">
      <h2 className="mb-2.5 ml-px flex items-center gap-2 text-[13px] text-muted-foreground">
        <Icon className={cn("size-3.5 mb-px", iconClassName)} />
        <span className="leading-none font-medium text-foreground">
          {label}
        </span>
      </h2>
      {children}
    </section>
  );
}

/** A list that folds behind "Show N more" past the first few entries. */
function Foldable<T>({
  items,
  render,
}: {
  items: T[];
  render: (item: T, i: number) => React.ReactNode;
}) {
  const [expanded, setExpanded] = useState(false);
  const shown = expanded ? items : items.slice(0, SHOWN);
  const hidden = items.length - shown.length;
  return (
    <>
      <ul className="flex list-none flex-col gap-1">{shown.map(render)}</ul>
      {hidden > 0 ? (
        <button
          type="button"
          onClick={() => setExpanded(true)}
          className="mt-2 text-[11px] font-medium cursor-pointer text-muted-foreground/50 hover:text-foreground"
        >
          Show {hidden} more
        </button>
      ) : null}
    </>
  );
}

export function VerificationReport({
  before,
  report,
  verified,
  spanCount,
  secondsToFirstTrace,
}: {
  /** The scan the plan was approved against — the "before" of the diff. */
  before: ScanData;
  report: AppliedReport;
  verified: boolean;
  spanCount?: number | null;
  secondsToFirstTrace?: number | null;
}) {
  const diff = useMemo(() => diffScans(report.scan, before), [report, before]);
  const instrumented = report.calls.filter((c) => c.instrumented).length;
  const skipped = report.calls.filter((c) => !c.instrumented);

  return (
    <Card className="flex max-h-[45%] shrink-0 flex-col overflow-hidden rounded-[36px] squircle:rounded-[36px] py-0">
      <CardContent className="scroll-fade no-scrollbar flex min-h-0 flex-1 flex-col overflow-y-auto px-5 py-5 pb-8">
        <Section
          label="What your agent did"
          Icon={IconCircleCheckFilled}
          iconClassName="text-emerald-500"
        >
          <p className="text-[11px] leading-relaxed text-muted-foreground">
            Instrumented {instrumented} of {report.calls.length} model calls
            {report.hudEnabled ? ", and enabled the dev HUD" : ""}.
            {verified && spanCount
              ? ` Your first trace landed${
                  secondsToFirstTrace
                    ? ` ${formatSeconds(secondsToFirstTrace)} later`
                    : ""
                } with ${spanCount} ${spanCount === 1 ? "span" : "spans"}.`
              : ""}
          </p>
          {skipped.length > 0 ? (
            <ul className="mt-2 flex list-none flex-col gap-1">
              {skipped.map((c) => (
                <li
                  key={c.id}
                  className="text-[11px] leading-relaxed text-muted-foreground"
                >
                  <span className="text-amber-600 dark:text-amber-400">
                    Skipped
                  </span>{" "}
                  {c.note ?? c.id}
                </li>
              ))}
            </ul>
          ) : null}
        </Section>

        {diff.hasChanges ? (
          <Section
            label="On the map"
            Icon={IconFileDiffFilled}
            iconClassName="text-muted-foreground"
          >
            <Foldable
              items={[
                ...diff.addedNodes.map((n) => ({ n, change: "added" as const })),
                ...diff.changedNodes.map((n) => ({
                  n,
                  change: "changed" as const,
                })),
                ...diff.removedNodes.map((n) => ({
                  n,
                  change: "removed" as const,
                })),
              ]}
              render={({ n, change }) => (
                <li
                  key={`${change}:${n.id}`}
                  className="flex items-center gap-2"
                >
                  {change === "added" ? (
                    <IconPlusFilled className="size-3 flex-none text-green-600 dark:text-green-400" />
                  ) : change === "changed" ? (
                    <IconEditFilled className="size-3 flex-none text-yellow-600 dark:text-yellow-400" />
                  ) : (
                    <IconMinus className="size-3 flex-none text-red-600 dark:text-red-400" />
                  )}
                  <span
                    className={cn(
                      "truncate text-[12px]",
                      change === "removed" &&
                        "text-muted-foreground line-through"
                    )}
                  >
                    {n.label}
                  </span>
                  <span className="shrink-0 text-[10px] text-muted-foreground">
                    {change === "changed"
                      ? "updated"
                      : KIND_STYLES[n.kind].label.toLowerCase()}
                  </span>
                </li>
              )}
            />
          </Section>
        ) : null}

        {report.filesChanged.length > 0 ? (
          <Section
            label={`Files changed · ${report.filesChanged.length}`}
            Icon={IconFileCodeFilled}
            iconClassName="text-muted-foreground"
          >
            <Foldable
              items={report.filesChanged}
              render={(path) => (
                <li
                  key={path}
                  className="truncate font-mono text-[10px] text-muted-foreground"
                  title={path}
                >
                  {path}
                </li>
              )}
            />
          </Section>
        ) : null}

        {report.warnings.length > 0 ? (
          <Section
            label="Heads up"
            Icon={IconAlertTriangleFilled}
            iconClassName="text-amber-500"
          >
            <ul className="flex list-none flex-col gap-1.5">
              {report.warnings.map((w) => (
                <li
                  key={w}
                  className="text-[11px] leading-relaxed text-muted-foreground"
                >
                  {w}
                </li>
              ))}
            </ul>
          </Section>
        ) : null}
      </CardContent>
    </Card>
  );
}

function formatSeconds(s: number): string {
  if (s < 90) return `${Math.round(s)}s`;
  if (s < 5400) return `${Math.round(s / 60)}min`;
  return `${Math.round(s / 3600)}h`;
}

"use client";

/**
 * Original design by Gustavo Fior (@gustavo-fior) and Foglamp Labs,
 * co-founded by Abdul Haidar. Extracted AS-IS from foglamp-labs/foglamp.
 */

import * as React from "react";

type FoglampLinkComponent = React.ElementType;

const FoglampLinkContext = React.createContext<FoglampLinkComponent>("a");

export type FoglampLinkProviderProps = {
	/** Router or link component that should render every FoglampLink below it. */
	component: FoglampLinkComponent;
	children: React.ReactNode;
};

export function FoglampLinkProvider({
	component,
	children,
}: FoglampLinkProviderProps) {
	return (
		<FoglampLinkContext.Provider value={component}>
			{children}
		</FoglampLinkContext.Provider>
	);
}

/**
 * A link with no wrapper of its own. The provider component receives the
 * original props directly, so the rendered DOM and styling stay with the
 * router's link implementation. A per-link component or `as` can override it.
 */
export type FoglampLinkProps<Component extends FoglampLinkComponent = "a"> =
	React.ComponentPropsWithRef<Component> & {
		component?: Component;
		as?: Component;
		/** Common router destination prop, available with the default anchor type. */
		to?: string;
	};

export function FoglampLink<Component extends FoglampLinkComponent = "a">({
	component,
	as,
	...props
}: FoglampLinkProps<Component>) {
	const providerComponent = React.useContext(FoglampLinkContext);
	const LinkComponent = component ?? as ?? providerComponent;

	return React.createElement(LinkComponent, props as React.ComponentPropsWithRef<Component>);
}

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/apps/web/src/components/scan/diff.ts; derived here under Apache-2.0.
 */
import type { GraphNode, ScanData } from "./scan";

export interface ScanDiff {
	addedNodes: GraphNode[];
	removedNodes: GraphNode[];
	changedNodes: GraphNode[];
	/** stat deltas, only the non-zero ones (e.g. { agents: +2 }). */
	statDeltas: Partial<Record<keyof ScanData["stats"], number>>;
	hasChanges: boolean;
}

export function diffScans(current: ScanData, previous: ScanData): ScanDiff {
	const prevById = new Map(previous.graph.nodes.map((n) => [n.id, n]));
	const curById = new Map(current.graph.nodes.map((n) => [n.id, n]));

	const addedNodes = current.graph.nodes.filter((n) => !prevById.has(n.id));
	const removedNodes = previous.graph.nodes.filter((n) => !curById.has(n.id));
	const changedNodes = current.graph.nodes.filter((n) => {
		const prev = prevById.get(n.id);
		if (!prev) return false;
		return prev.label !== n.label || prev.kind !== n.kind || prev.sub !== n.sub;
	});

	const statDeltas: ScanDiff["statDeltas"] = {};
	for (const key of Object.keys(current.stats) as (keyof ScanData["stats"])[]) {
		const delta = current.stats[key] - previous.stats[key];
		if (delta !== 0) statDeltas[key] = delta;
	}

	return {
		addedNodes,
		removedNodes,
		changedNodes,
		statDeltas,
		hasChanges:
			addedNodes.length + removedNodes.length + changedNodes.length > 0 ||
			Object.keys(statDeltas).length > 0,
	};
}

/* Derived for the Foglamp Design System portal by the project contributors.
 * It adapts Foglamp concepts and assets; this new integration code is not represented as upstream-authored.
 * Original project: Gustavo Fior (@gustavo-fior), Abdul Haidar, Foglamp Labs; Apache-2.0 source project.
 */
export function faviconUrl(domain: string): string {
	return `/api/favicon?domain=${encodeURIComponent(domain)}`;
}

/**
 * Product-accurate icon domains for models: agents often emit the provider's
 * corporate domain (google.com → the "G"), but the model deserves its product
 * mark (Gemini's spark). Keyed by label match, applied only to model items.
 */
const MODEL_DOMAIN_FIXES: [RegExp, string][] = [
	[/gemini/i, "gemini.google.com"],
	[/claude/i, "claude.ai"],
	[/gpt|^o[0-9]/i, "openai.com"],
];

export function modelDomain(
	label: string,
	domain?: string,
): string | undefined {
	for (const [re, fixed] of MODEL_DOMAIN_FIXES) {
		if (re.test(label)) return fixed;
	}
	return domain;
}

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/apps/web/src/components/scan/fold-graph.ts; derived here under Apache-2.0.
 */
import type { GraphEdge, NodeKind, ScanData } from "./scan";

export interface Embed {
	id: string;
	label: string;
	kind: "model" | "tool";
	domain?: string;
}

export interface FoldedNode {
	id: string;
	label: string;
	kind: NodeKind;
	domain?: string;
	sub?: string;
	detail?: string;
	group?: string;
	sourceRef?: string;
	/** Models and tools this node uses, rendered inline (models first). */
	embeds: Embed[];
}

export interface FoldedGraph {
	nodes: FoldedNode[];
	edges: GraphEdge[];
}

const FOLDED: ReadonlySet<NodeKind> = new Set<NodeKind>(["model", "tool"]);

export function foldGraph(graph: ScanData["graph"]): FoldedGraph {
	const byId = new Map(graph.nodes.map((n) => [n.id, n]));
	const embedsByNode = new Map<string, Embed[]>();

	for (const e of graph.edges) {
		const target = byId.get(e.to);
		const source = byId.get(e.from);
		if (!target || !source || !FOLDED.has(target.kind)) continue;
		const arr = embedsByNode.get(source.id) ?? [];
		if (!arr.some((x) => x.id === target.id)) {
			arr.push({
				id: target.id,
				label: target.label,
				kind: target.kind as "model" | "tool",
				domain: target.domain,
			});
		}
		embedsByNode.set(source.id, arr);
	}

	const nodes: FoldedNode[] = graph.nodes
		.filter((n) => !FOLDED.has(n.kind))
		.map((n) => ({
			id: n.id,
			label: n.label,
			kind: n.kind,
			domain: n.domain,
			sub: n.sub,
			detail: n.detail,
			group: n.group,
			sourceRef: n.sourceRef,
			// models before tools
			embeds: (embedsByNode.get(n.id) ?? []).sort((a, b) =>
				a.kind === b.kind ? 0 : a.kind === "model" ? -1 : 1,
			),
		}));

	const alive = new Set(nodes.map((n) => n.id));
	const edges = graph.edges.filter((e) => alive.has(e.from) && alive.has(e.to));

	return { nodes, edges };
}

/* Derived for the Foglamp Design System portal by the project contributors.
 * It adapts Foglamp concepts and assets; this new integration code is not represented as upstream-authored.
 * Original project: Gustavo Fior (@gustavo-fior), Abdul Haidar, Foglamp Labs; Apache-2.0 source project.
 */
import { z } from "zod";

import { type GraphNode, ScanData } from "./scan";

/** Schema version for the plan payloads, independent of ScanData's version. */
export const PLAN_VERSION = 1;

// ---------------------------------------------------------------------------
// State machine
// ---------------------------------------------------------------------------

/**
 * The lifecycle of a plan. Persisted as text; the transition table below is the
 * only thing allowed to move a row between these.
 *
 *  - awaiting_approval: uploaded, the agent is polling, the user hasn't acted
 *  - approved:          the user said yes; the agent hasn't picked it up yet
 *  - applying:          the agent resumed and is editing the repo
 *  - applied:           code changes are in; waiting for the first real trace
 *  - verified:          a real span arrived — onboarding is complete
 *  - rejected:          the user said no; the agent exits cleanly
 *  - expired:           nobody acted before expiresAt; swept by the cron
 *  - failed:            the agent gave up (it reports which stage)
 *
 * Note there is no separate `waiting_for_trace` state: it would always coincide
 * exactly with `applied`, and two states that must flip together are a bug
 * waiting to happen. The UI renders `applied` as "Waiting for your first real
 * trace" — the user-facing distinction is copy, not state.
 */
export const PLAN_STATUSES = [
  "awaiting_approval",
  "approved",
  "applying",
  "applied",
  "verified",
  "rejected",
  "expired",
  "failed",
] as const;
export const PlanStatus = z.enum(PLAN_STATUSES);
export type PlanStatus = z.infer<typeof PlanStatus>;

/** Statuses from which nothing further can happen. */
export const TERMINAL_STATUSES = ["verified", "rejected", "expired", "failed"] as const;

/**
 * The only legal moves. Anything not listed is rejected — a status write can
 * never silently overwrite a terminal state, so a late-arriving agent request
 * can't un-reject or un-expire a plan.
 */
const TRANSITIONS: Record<PlanStatus, readonly PlanStatus[]> = {
  awaiting_approval: ["approved", "rejected", "expired"],
  approved: ["applying", "expired", "failed"],
  // `expired` here covers the agent that died mid-apply (crashed, laptop
  // closed): without it the plan would sit in `applying` forever and the
  // review page would spin until the end of time. The TTL is generous (24h),
  // so a healthy apply — minutes — never gets close.
  applying: ["applied", "expired", "failed"],
  applied: ["verified", "failed"],
  // Terminal — absorbing states.
  verified: [],
  rejected: [],
  expired: [],
  failed: [],
};

export function isTerminalStatus(status: PlanStatus): boolean {
  return (TERMINAL_STATUSES as readonly string[]).includes(status);
}

/**
 * Can a plan move from `from` to `to`? Pure — no I/O, no clock, no database.
 *
 * A self-transition (`from === to`) is always legal so that retries and
 * duplicate requests are no-ops rather than errors: the caller's conditional
 * `UPDATE ... WHERE status = <expected>` simply matches zero rows the second
 * time, which is exactly the idempotency we want.
 */
export function canTransition(from: PlanStatus, to: PlanStatus): boolean {
  if (from === to) return true;
  return TRANSITIONS[from].includes(to);
}

/** The statuses a plan can still leave — i.e. worth polling for a change. */
export function isPending(status: PlanStatus): boolean {
  return !isTerminalStatus(status);
}

// ---------------------------------------------------------------------------
// Shared primitives
// ---------------------------------------------------------------------------

/** Where something lives in the repo, e.g. "src/agents/support.ts:42". */
const SourceRef = z.string().min(1).max(160);

/** One short sentence explaining a recommendation. Never contains code. */
const Rationale = z.string().min(1).max(200);

/** How sure the agent is. Drives the review UI's emphasis, nothing else. */
export const Confidence = z.enum(["high", "medium", "low"]);
export type Confidence = z.infer<typeof Confidence>;

/**
 * A static name attached to a span (`agentName`, `workflowName`, `traceName`).
 * The constraint that matters: these must be stable literals so they group
 * across runs. Anything dynamic (an id, slug, URL, timestamp) belongs in
 * metadata / workflowRunId / sessionId / customer.id instead.
 */
const StaticName = z.string().min(1).max(48);

/**
 * A described source for a dynamic value, e.g. how to derive a workflowRunId.
 * Prose, not code: "the job id from the queue payload". The agent turns this
 * into an expression when it applies the plan.
 */
const ValueSource = z.string().min(1).max(160);

/** The AI SDK major this repo is on — decides wrap() vs fog.integration(). */
const SdkInfo = z
  .object({
    major: z.union([z.literal(4), z.literal(5), z.literal(6), z.literal(7)]),
    /** Exact installed version string, e.g. "5.0.12". Display only. */
    version: z.string().min(1).max(32),
  })
  .strict();
export type SdkInfo = z.infer<typeof SdkInfo>;

/** A single model call site found in the repo. */
const CallSite = z
  .object({
    /** Unique within the plan; referenced by decisions. */
    id: z.string().min(1).max(64),
    /** The AI SDK function called, e.g. "streamText". */
    fn: z.string().min(1).max(40),
    sourceRef: SourceRef,
    /** Model id if statically determinable, e.g. "gpt-4o". */
    modelId: z.string().max(64).optional(),
  })
  .strict();
export type CallSite = z.infer<typeof CallSite>;

// ---------------------------------------------------------------------------
// Decisions — the reviewable part
// ---------------------------------------------------------------------------

/**
 * A named agent flow. `oneOff` marks calls that aren't a repeated agent at all
 * (a one-shot classification, a title generator) — those get a `traceName`
 * rather than an `agentName`.
 */
const AgentDecision = z
  .object({
    id: z.string().min(1).max(64),
    name: StaticName,
    /** Call site ids this name covers. */
    callIds: z.array(z.string().min(1).max(64)).min(1).max(50),
    oneOff: z.boolean().default(false),
    confidence: Confidence,
    sourceRef: SourceRef,
    rationale: Rationale,
  })
  .strict();
export type AgentDecision = z.infer<typeof AgentDecision>;

/**
 * A multi-step pipeline whose calls share a workflowName + workflowRunId.
 * Batch jobs, crons and pipelines are workflows — never sessions.
 */
const WorkflowDecision = z
  .object({
    id: z.string().min(1).max(64),
    name: StaticName,
    callIds: z.array(z.string().min(1).max(64)).min(1).max(50),
    /** How to derive the per-run id that ties the steps together. */
    runIdSource: ValueSource,
    confidence: Confidence,
    sourceRef: SourceRef,
    rationale: Rationale,
  })
  .strict();
export type WorkflowDecision = z.infer<typeof WorkflowDecision>;

/**
 * A real end-user conversation thread. Only genuine back-and-forth qualifies —
 * one-off calls, background jobs, batches and pipelines must not be labelled
 * with a sessionId.
 */
const SessionDecision = z
  .object({
    id: z.string().min(1).max(64),
    /** Human label for the review UI, e.g. "Support chat". */
    label: z.string().min(1).max(48),
    callIds: z.array(z.string().min(1).max(64)).min(1).max(50),
    /** How to derive the conversation id, e.g. "the thread id on the request". */
    sessionIdSource: ValueSource,
    confidence: Confidence,
    sourceRef: SourceRef,
    rationale: Rationale,
  })
  .strict();
export type SessionDecision = z.infer<typeof SessionDecision>;

/**
 * Per-customer spend attribution. Only recommended when the app clearly serves
 * distinct end-customers or tenants; `recommended: false` is the common and
 * correct answer for a single-tenant app.
 */
const CustomerDecision = z
  .object({
    recommended: z.boolean(),
    /** How to derive customer.id. Required when recommended. */
    idSource: ValueSource.optional(),
    nameSource: ValueSource.optional(),
    imageUrlSource: ValueSource.optional(),
    confidence: Confidence,
    rationale: Rationale,
  })
  .strict()
  .refine((c) => !c.recommended || Boolean(c.idSource), {
    message: "idSource is required when customer attribution is recommended",
  });
export type CustomerDecision = z.infer<typeof CustomerDecision>;

const Decisions = z
  .object({
    agents: z.array(AgentDecision).max(40).default([]),
    workflows: z.array(WorkflowDecision).max(20).default([]),
    sessions: z.array(SessionDecision).max(20).default([]),
    customer: CustomerDecision,
  })
  .strict();
export type Decisions = z.infer<typeof Decisions>;

// ---------------------------------------------------------------------------
// DetectedPlan — what the agent uploads before touching any code
// ---------------------------------------------------------------------------

export const DetectedPlan = z
  .object({
    version: z.literal(PLAN_VERSION),
    sdk: SdkInfo,
    /** Whether the repo has a React UI — decides if the HUD is offered. */
    hasReactUi: z.boolean().default(false),
    /** The architecture map, in the public Scan contract's exact shape. */
    scan: ScanData,
    calls: z.array(CallSite).max(200).default([]),
    decisions: Decisions,
  })
  .strict()
  .superRefine((plan, ctx) => {
    const callIds = new Set(plan.calls.map((c) => c.id));
    const seen = new Set<string>();
    for (const c of plan.calls) {
      if (seen.has(c.id)) {
        ctx.addIssue({ code: "custom", path: ["calls"], message: "call ids must be unique" });
        break;
      }
      seen.add(c.id);
    }
    const groups = [
      ["agents", plan.decisions.agents],
      ["workflows", plan.decisions.workflows],
      ["sessions", plan.decisions.sessions],
    ] as const;
    for (const [key, list] of groups) {
      for (const d of list) {
        for (const id of d.callIds) {
          if (!callIds.has(id)) {
            ctx.addIssue({
              code: "custom",
              path: ["decisions", key],
              message: `unknown call id "${id}"`,
            });
          }
        }
      }
    }
  });
export type DetectedPlan = z.infer<typeof DetectedPlan>;

/**
 * What the agent receives back once the user approves. Stage 1 hands back the
 * decisions unchanged (the review UI is read-only); the shape is separate from
 * DetectedPlan so Stage 2 can return user-edited decisions without the agent
 * needing to change how it reads them.
 */
export const ApprovedPlan = z
  .object({
    version: z.literal(PLAN_VERSION),
    decisions: Decisions,
  })
  .strict();
export type ApprovedPlan = z.infer<typeof ApprovedPlan>;

// ---------------------------------------------------------------------------
// PlanEdits — what the review UI may change before approving (Stage 2)
// ---------------------------------------------------------------------------
//
// The browser never sends a whole Decisions object: it sends a small patch
// keyed by decision id, and the server applies it onto the DETECTED decisions.
// That keeps callIds, sourceRefs, rationales and confidences server-
// authoritative — an edited approval can rename things and adjust sources,
// never invent call sites or rewrite the evidence.

const AgentEdit = z
  .object({
    id: z.string().min(1).max(64),
    name: StaticName.optional(),
    oneOff: z.boolean().optional(),
  })
  .strict();

const WorkflowEdit = z
  .object({
    id: z.string().min(1).max(64),
    name: StaticName.optional(),
    runIdSource: ValueSource.optional(),
  })
  .strict();

const SessionEdit = z
  .object({
    id: z.string().min(1).max(64),
    label: z.string().min(1).max(48).optional(),
    sessionIdSource: ValueSource.optional(),
  })
  .strict();

const CustomerEdit = z
  .object({
    recommended: z.boolean().optional(),
    idSource: ValueSource.optional(),
  })
  .strict();

export const PlanEdits = z
  .object({
    agents: z.array(AgentEdit).max(40).default([]),
    workflows: z.array(WorkflowEdit).max(20).default([]),
    sessions: z.array(SessionEdit).max(20).default([]),
    customer: CustomerEdit.optional(),
  })
  .strict();
export type PlanEdits = z.infer<typeof PlanEdits>;

export type ApplyEditsResult =
  | {
      ok: true;
      decisions: Decisions;
      /** Decisions that actually changed — 0 means the edits were all no-ops. */
      editedCount: number;
    }
  | { ok: false; errors: string[] };

/** Trimmed value, or undefined when the edit is absent or trims to nothing —
 *  an all-whitespace input falls back to the detected value instead of
 *  producing an empty name. */
function cleaned(value: string | undefined): string | undefined {
  const t = value?.trim();
  return t ? t : undefined;
}

/**
 * Apply user edits onto the detected decisions, producing what the agent will
 * receive. Pure. Unknown ids are errors (the UI can only edit what was
 * detected); the merged result is re-validated through `Decisions`, so caps
 * and the customer `recommended → idSource` invariant hold no matter what the
 * browser sent.
 */
export function applyPlanEdits(
  detected: Decisions,
  edits: PlanEdits,
): ApplyEditsResult {
  const errors: string[] = [];
  let editedCount = 0;

  function mergeList<
    T extends { id: string },
    E extends { id: string },
  >(
    kind: string,
    list: T[],
    patches: E[],
    apply: (item: T, patch: E) => T,
  ): T[] {
    const byId = new Map(list.map((d) => [d.id, d] as const));
    for (const patch of patches) {
      const cur = byId.get(patch.id);
      if (!cur) {
        errors.push(`decisions.${kind}: unknown id "${patch.id}"`);
        continue;
      }
      const next = apply(cur, patch);
      if (JSON.stringify(next) !== JSON.stringify(cur)) {
        editedCount += 1;
        byId.set(patch.id, next);
      }
    }
    return list.map((d) => byId.get(d.id)!);
  }

  const agents = mergeList(
    "agents",
    detected.agents,
    edits.agents,
    (a, e) => ({
      ...a,
      name: cleaned(e.name) ?? a.name,
      oneOff: e.oneOff ?? a.oneOff,
    }),
  );
  const workflows = mergeList(
    "workflows",
    detected.workflows,
    edits.workflows,
    (w, e) => ({
      ...w,
      name: cleaned(e.name) ?? w.name,
      runIdSource: cleaned(e.runIdSource) ?? w.runIdSource,
    }),
  );
  const sessions = mergeList(
    "sessions",
    detected.sessions,
    edits.sessions,
    (s, e) => ({
      ...s,
      label: cleaned(e.label) ?? s.label,
      sessionIdSource: cleaned(e.sessionIdSource) ?? s.sessionIdSource,
    }),
  );

  let customer = detected.customer;
  if (edits.customer) {
    const next = {
      ...customer,
      recommended: edits.customer.recommended ?? customer.recommended,
      idSource: cleaned(edits.customer.idSource) ?? customer.idSource,
    };
    if (JSON.stringify(next) !== JSON.stringify(customer)) {
      editedCount += 1;
      customer = next;
    }
  }

  if (errors.length > 0) return { ok: false, errors };

  const parsed = Decisions.safeParse({ agents, workflows, sessions, customer });
  if (!parsed.success) return { ok: false, errors: flatten(parsed.error.issues) };
  return { ok: true, decisions: parsed.data, editedCount };
}

// ---------------------------------------------------------------------------
// AppliedReport — what the agent uploads after editing the repo
// ---------------------------------------------------------------------------

const AppliedCall = z
  .object({
    id: z.string().min(1).max(64),
    instrumented: z.boolean(),
    /** Why it was skipped, when it wasn't instrumented. */
    note: z.string().max(160).optional(),
  })
  .strict();

export const AppliedReport = z
  .object({
    version: z.literal(PLAN_VERSION),
    /** The map as it stands after instrumentation — powers the after-state diff. */
    scan: ScanData,
    calls: z.array(AppliedCall).max(200).default([]),
    /** Repo-relative paths only. No diffs, no contents. */
    filesChanged: z.array(z.string().min(1).max(200)).max(100).default([]),
    /** Anything the user should know, e.g. "flush() needed in the cron entry". */
    warnings: z.array(z.string().min(1).max(200)).max(20).default([]),
    hudEnabled: z.boolean().default(false),
  })
  .strict();
export type AppliedReport = z.infer<typeof AppliedReport>;

/** The stage an agent gave up at, reported on failure. */
export const FailureStage = z.enum(["detect", "apply", "verify"]);
export type FailureStage = z.infer<typeof FailureStage>;

// ---------------------------------------------------------------------------
// Validation helpers — same shape as validateScan (scan.ts)
// ---------------------------------------------------------------------------

export interface PlanValidateOk<T> {
  ok: true;
  data: T;
}
export interface PlanValidateErr {
  ok: false;
  /** Human-readable lines like `decisions.agents.0.name: too long`. */
  errors: string[];
}

function flatten(issues: z.ZodIssue[]): string[] {
  return issues.map((issue) => {
    const path = issue.path.join(".") || "(root)";
    return `${path}: ${issue.message}`;
  });
}

export function validateDetectedPlan(
  input: unknown,
): PlanValidateOk<DetectedPlan> | PlanValidateErr {
  const res = DetectedPlan.safeParse(input);
  if (res.success) return { ok: true, data: res.data };
  return { ok: false, errors: flatten(res.error.issues) };
}

export function validateAppliedReport(
  input: unknown,
): PlanValidateOk<AppliedReport> | PlanValidateErr {
  const res = AppliedReport.safeParse(input);
  if (res.success) return { ok: true, data: res.data };
  return { ok: false, errors: flatten(res.error.issues) };
}

// ---------------------------------------------------------------------------
// Graph audit — degenerate-map detection
// ---------------------------------------------------------------------------

/**
 * Structural sanity checks on the architecture map, beyond what the schema can
 * express. A graph that is just the decisions list re-drawn — all agent nodes,
 * barely any wiring, no models or stores — defeats the review page: the user
 * can't judge a plan against a picture that isn't their system. These lines
 * join the 422 `details` on upload, so the agent self-corrects and retries.
 *
 * Thresholds are deliberately loose: a tiny repo with two agents and a route
 * passes untouched. Only maps that are BOTH sizable and degenerate fail.
 */
export function auditPlanGraph(plan: DetectedPlan): string[] {
  const { nodes, edges } = plan.scan.graph;
  const errors: string[] = [];
  const ofKind = (kind: GraphNode["kind"]) =>
    nodes.filter((n) => n.kind === kind);

  if (plan.calls.length > 0 && ofKind("model").length === 0) {
    errors.push(
      "scan.graph: no model nodes — add one model node per distinct model the calls use, wired from the agents that call it",
    );
  }

  const agents = ofKind("agent");
  if (nodes.length >= 8 && agents.length / nodes.length > 0.8) {
    errors.push(
      `scan.graph: ${agents.length} of ${nodes.length} nodes are agents — this is the decisions list re-drawn, not the architecture; add the models, services, stores and third-party APIs the flows touch`,
    );
  }

  if (nodes.length >= 6 && edges.length * 2 < nodes.length) {
    errors.push(
      `scan.graph: only ${edges.length} edges for ${nodes.length} nodes — most of the map floats unconnected; wire each flow end to end, entry through model`,
    );
  }

  if (nodes.length >= 6) {
    const connected = new Set(edges.flatMap((e) => [e.from, e.to]));
    const stranded = agents.filter((n) => !connected.has(n.id));
    if (agents.length >= 3 && stranded.length * 2 > agents.length) {
      errors.push(
        `scan.graph: ${stranded.length} of ${agents.length} agent nodes have no edges at all — connect each agent FROM what triggers it and TO what it uses`,
      );
    }
    if (ofKind("entry").length === 0 && ofKind("cron").length === 0) {
      errors.push(
        "scan.graph: no entry or cron nodes — add the real routes, pages, webhooks or scheduled jobs that trigger the AI work",
      );
    }
  }

  return errors;
}

// ---------------------------------------------------------------------------
// Summary — the one-line headline on the review page
// ---------------------------------------------------------------------------

export interface PlanSummary {
  agents: number;
  workflows: number;
  sessions: number;
  calls: number;
}

/** Counts for "Foglamp found 4 agents, 2 workflows, …". */
export function summarizePlan(plan: DetectedPlan): PlanSummary {
  return {
    agents: plan.decisions.agents.length,
    workflows: plan.decisions.workflows.length,
    sessions: plan.decisions.sessions.length,
    calls: plan.calls.length,
  };
}

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/apps/web/src/components/scan/layout.ts; derived here under Apache-2.0.
 */
import type { GraphEdge } from "./scan";
import type { ELK, ElkNode } from "elkjs/lib/elk-api";

// elkjs is imported lazily, and via elk-api + the fake in-process worker
// instead of elk.bundled.js: the bundle's own `require("./elk-worker.min.js")`
// doesn't survive Next bundling ("_Worker is not a constructor" on the OG
// route), while an explicit workerFactory works in browser and Node alike.
let elkInstance: ELK | null = null;
async function getElk(): Promise<ELK> {
	if (!elkInstance) {
		const elkApi = (await import("elkjs/lib/elk-api.js")) as {
			default: (new (opts: object) => ELK) | { default: new (opts: object) => ELK };
		};
		// Bun exposes `self` without a document, so elkjs mistakes its main
		// thread for a web worker and never exports the fake worker constructor.
		// Hide it only during Bun's synchronous module evaluation.
		let worker: Record<string, unknown>;
		const bunRequire = (import.meta as ImportMeta & {
			require?: (id: string) => Record<string, unknown>;
		}).require;
		if ("Bun" in globalThis && typeof bunRequire === "function" && typeof document === "undefined") {
			const selfDescriptor = Object.getOwnPropertyDescriptor(globalThis, "self");
			try {
				Object.defineProperty(globalThis, "self", {
					value: undefined,
					configurable: true,
				});
				worker = bunRequire("elkjs/lib/elk-worker.min.js");
			} finally {
				if (selfDescriptor) Object.defineProperty(globalThis, "self", selfDescriptor);
				else Reflect.deleteProperty(globalThis, "self");
			}
		} else {
			// @ts-expect-error — no types for the worker entry
			worker = await import("elkjs/lib/elk-worker.min.js");
		}
		// Both modules are CJS; depending on the bundler (turbopack, webpack,
		// Vercel's nft trace) the constructor lands on the module, .default, or
		// .default.default. Probe every shape instead of trusting one.
		const ELKCtor = (
			typeof elkApi.default === "function"
				? elkApi.default
				: elkApi.default.default
		) as new (
			opts: object,
		) => ELK;
		const workerNs = worker as {
			Worker?: unknown;
			default?: { Worker?: unknown };
		};
		const FakeWorker = (workerNs.Worker ??
			workerNs.default?.Worker ??
			workerNs.default) as new (
			url?: string,
		) => Worker;
		if (typeof FakeWorker !== "function") {
			throw new Error("elk-worker module shape not recognized");
		}
		elkInstance = new ELKCtor({
			workerFactory: (url?: string) => new FakeWorker(url),
		});
	}
	return elkInstance;
}

export interface SizedNode {
	id: string;
	width: number;
	height: number;
	group?: string;
}

export type PlacedNode<T extends SizedNode> = T & { x: number; y: number };

export interface GroupBox {
	id: string;
	label: string;
	x: number;
	y: number;
	width: number;
	height: number;
}

export interface RenderedEdge {
	/** Endpoint ids — node ids, or a group id for edges attached to a stack. */
	from: string;
	to: string;
	label?: string;
	points: { x: number; y: number }[];
	/** ELK-placed label center. ELK reserves space for labels during routing,
	 *  so labels positioned here cannot collide; absent for label-less edges. */
	labelPos?: { x: number; y: number };
	/** Indices of the original input edges this rendered edge represents. */
	orig: number[];
}

/** Label box ELK reserves while routing — mirrors the rendered chip
 *  (text-xs ≈ 6.2px/char + px-2 padding, py-0.5 → 22px tall). */
const LABEL_H = 22;
function labelDims(text: string): { width: number; height: number } {
	return { width: Math.round(text.length * 6) + 14, height: LABEL_H };
}

export interface Layout<T extends SizedNode> {
	nodes: PlacedNode<T>[];
	groups: GroupBox[];
	edges: RenderedEdge[];
	width: number;
	height: number;
}

const GROUP_PAD = { top: 46, right: 16, bottom: 16, left: 16 };

export async function layoutGraph<T extends SizedNode>(
	nodes: T[],
	edges: GraphEdge[],
	opts: {
		/** Tighter layer gaps for small marketing embeds. */
		compact?: boolean;
		/** Flow direction — RIGHT (default) or DOWN (portrait embeds). */
		direction?: "RIGHT" | "DOWN";
		/**
		 * Group labels (case-insensitive) laid out LEFT-TO-RIGHT inside their box
		 * instead of the default vertical stack — workflow pipelines read better
		 * horizontal.
		 */
		horizontalGroups?: string[];
	} = {},
): Promise<Layout<T>> {
	const elk = await getElk();
	const nodeById = new Map(nodes.map((n) => [n.id, n]));

	// Group membership, in order of first appearance.
	const groupNames: string[] = [];
	const membersByGroup = new Map<string, T[]>();
	for (const n of nodes) {
		if (!n.group) continue;
		if (!membersByGroup.has(n.group)) {
			membersByGroup.set(n.group, []);
			groupNames.push(n.group);
		}
		membersByGroup.get(n.group)!.push(n);
	}
	const groupIdOf = (name: string) => `group:${groupNames.indexOf(name)}`;
	const groupOfNode = (id: string) => nodeById.get(id)?.group;

	const horizontalNames = new Set(
		(opts.horizontalGroups ?? []).map((n) => n.toLowerCase()),
	);

	// ── Pass A: each group in isolation (top-to-bottom, or left-to-right for
	//    horizontal groups) ─────────────────────────────────────────────────────
	const groupLayouts = new Map<
		string,
		{
			size: { width: number; height: number };
			children: Map<string, { x: number; y: number }>;
			edges: {
				points: { x: number; y: number }[];
				labelPos?: { x: number; y: number };
				origIndex: number;
			}[];
		}
	>();

	for (const name of groupNames) {
		const members = membersByGroup.get(name)!;
		const memberIds = new Set(members.map((m) => m.id));
		const internal = edges
			.map((e, i) => ({ e, i }))
			.filter(({ e }) => memberIds.has(e.from) && memberIds.has(e.to));

		const horizontal = horizontalNames.has(name.toLowerCase());
		const input: ElkNode = {
			id: "root",
			layoutOptions: {
				"elk.algorithm": "layered",
				"elk.direction": horizontal ? "RIGHT" : "DOWN",
				"elk.edgeRouting": "ORTHOGONAL",
				"elk.layered.spacing.nodeNodeBetweenLayers": horizontal ? "40" : "30",
				"elk.spacing.nodeNode": "18",
				"elk.spacing.edgeNode": "14",
				"elk.edgeLabels.inline": "true",
				"elk.spacing.edgeLabel": "4",
				"elk.padding": `[top=${GROUP_PAD.top},left=${GROUP_PAD.left},bottom=${GROUP_PAD.bottom},right=${GROUP_PAD.right}]`,
			},
			children: members.map((m) => ({
				id: m.id,
				width: m.width,
				height: m.height,
			})),
			edges: internal.map(({ e, i }) => ({
				id: `e${i}`,
				sources: [e.from],
				targets: [e.to],
				...(e.label
					? { labels: [{ id: `el${i}`, text: e.label, ...labelDims(e.label) }] }
					: {}),
			})),
		};
		const res = await elk.layout(input);
		const children = new Map<string, { x: number; y: number }>();
		for (const c of res.children ?? [])
			children.set(c.id, { x: c.x ?? 0, y: c.y ?? 0 });
		const groupEdges = (res.edges ?? []).map((el) => {
			const sec = el.sections?.[0];
			const lbl = el.labels?.[0];
			return {
				origIndex: Number(el.id.slice(1)),
				points: sec
					? [sec.startPoint, ...(sec.bendPoints ?? []), sec.endPoint]
					: [],
				labelPos:
					lbl && lbl.x != null && lbl.y != null
						? {
								x: lbl.x + (lbl.width ?? 0) / 2,
								y: lbl.y + (lbl.height ?? 0) / 2,
							}
						: undefined,
			};
		});
		groupLayouts.set(name, {
			size: { width: res.width ?? 0, height: res.height ?? 0 },
			children,
			edges: groupEdges,
		});
	}

	// ── Pass B: root graph — ungrouped nodes + group boxes, left-to-right ──────
	// Cross-group edges are remapped to the group box and deduped.
	type RootEdge = { from: string; to: string; label?: string; orig: number[] };
	const rootEdges = new Map<string, RootEdge>();
	edges.forEach((e, i) => {
		const gFrom = groupOfNode(e.from);
		const gTo = groupOfNode(e.to);
		if (gFrom && gFrom === gTo) return; // internal — handled in pass A
		const from = gFrom ? groupIdOf(gFrom) : e.from;
		const to = gTo ? groupIdOf(gTo) : e.to;
		const key = `${from}→${to}`;
		const cur = rootEdges.get(key);
		if (cur) {
			cur.orig.push(i);
			if (!cur.label && e.label) cur.label = e.label;
		} else {
			rootEdges.set(key, { from, to, label: e.label, orig: [i] });
		}
	});

	const ungrouped = nodes.filter((n) => !n.group);
	const rootChildren: ElkNode[] = [
		...ungrouped.map((n) => ({ id: n.id, width: n.width, height: n.height })),
		...groupNames.map((name) => ({
			id: groupIdOf(name),
			width: groupLayouts.get(name)!.size.width,
			height: groupLayouts.get(name)!.size.height,
		})),
	];
	const dense = rootChildren.length > 12;
	const rootInput: ElkNode = {
		id: "root",
		layoutOptions: {
			"elk.algorithm": "layered",
			"elk.direction": opts.direction ?? "RIGHT",
			"elk.edgeRouting": "ORTHOGONAL",
			"elk.layered.mergeEdges": "true",
			// Layer gaps shrank when labels became ELK's job: inline labels reserve
			// their own room mid-edge, so the blanket spacing no longer carries them.
			"elk.layered.spacing.nodeNodeBetweenLayers": opts.compact
				? "56"
				: dense
					? "56"
					: "72",
			"elk.spacing.nodeNode": dense ? "18" : "26",
			"elk.spacing.edgeNode": dense ? "16" : "24",
			"elk.spacing.edgeEdge": "14",
			// BRANDES_KOEPF/BALANCED packs rows far tighter than NETWORK_SIMPLEX,
			// which trades area for straight edges and spread big maps out into
			// sparse, bureaucratic grids. Post-compaction then pulls layers together.
			"elk.layered.nodePlacement.strategy": "BRANDES_KOEPF",
			"elk.layered.nodePlacement.bk.fixedAlignment": "BALANCED",
			"elk.layered.compaction.postCompaction.strategy": "EDGE_LENGTH",
			"elk.edgeLabels.inline": "true",
			"elk.spacing.edgeLabel": "4",
			"elk.padding": "[top=16,left=16,bottom=16,right=16]",
		},
		children: rootChildren,
		edges: [...rootEdges.values()].map((e, i) => ({
			id: `r${i}`,
			sources: [e.from],
			targets: [e.to],
			...(e.label
				? { labels: [{ id: `rl${i}`, text: e.label, ...labelDims(e.label) }] }
				: {}),
		})),
	};
	const rootRes = await elk.layout(rootInput);
	const rootPos = new Map<string, { x: number; y: number }>();
	for (const c of rootRes.children ?? [])
		rootPos.set(c.id, { x: c.x ?? 0, y: c.y ?? 0 });

	// ── Row snap ────────────────────────────────────────────────────────────────
	// ELK's placement often leaves items that read as one row a few px apart
	// (see: two cards nearly level but off by ~15px). Cluster root-level items
	// whose vertical centers are within SNAP_TOL and align each cluster to its
	// mean center. Items inside one cluster can't collide — same-column items
	// this close would already overlap. Edge endpoints are shifted to match
	// below, keeping orthogonal routes orthogonal.
	const SNAP_TOL = 20;
	const rowDelta = new Map<string, number>();
	{
		const items = rootChildren
			.map((c) => {
				const pos = rootPos.get(c.id);
				return pos
					? { id: c.id, h: c.height ?? 0, centerY: pos.y + (c.height ?? 0) / 2 }
					: null;
			})
			.filter((i): i is NonNullable<typeof i> => i !== null)
			.sort((a, b) => a.centerY - b.centerY);
		let cluster: typeof items = [];
		const flush = () => {
			if (cluster.length < 2) return;
			const mean = cluster.reduce((s, i) => s + i.centerY, 0) / cluster.length;
			for (const i of cluster) {
				const dy = mean - i.centerY;
				if (dy === 0) continue;
				rowDelta.set(i.id, dy);
				const pos = rootPos.get(i.id)!;
				rootPos.set(i.id, { x: pos.x, y: pos.y + dy });
			}
		};
		for (const item of items) {
			if (
				cluster.length > 0 &&
				item.centerY - cluster[cluster.length - 1]!.centerY <= SNAP_TOL
			) {
				cluster.push(item);
			} else {
				flush();
				cluster = [item];
			}
		}
		flush();
	}

	/** Shift a root edge's endpoints by their nodes' snap deltas, preserving
	 *  orthogonality: the endpoint's adjoining horizontal stub moves with it,
	 *  so only the connecting vertical run changes length. */
	function snapEdgePoints(
		points: { x: number; y: number }[],
		fromId: string,
		toId: string,
	): { x: number; y: number }[] {
		const dS = rowDelta.get(fromId) ?? 0;
		const dT = rowDelta.get(toId) ?? 0;
		if ((dS === 0 && dT === 0) || points.length < 2) return points;
		const p = points.map((pt) => ({ ...pt }));
		const n = p.length;
		const horizontal = (a: { y: number }, b: { y: number }) =>
			Math.abs(a.y - b.y) < 0.5;
		p[0]!.y += dS;
		p[n - 1]!.y += dT;
		if (n === 2) return p; // straight edge: both ends snapped, stays straight-ish
		if (horizontal(points[0]!, points[1]!) && n > 3) p[1]!.y += dS;
		if (horizontal(points[n - 2]!, points[n - 1]!) && n > 3) p[n - 2]!.y += dT;
		if (n === 3) {
			// Single bend: keep whichever adjoining segment was horizontal aligned.
			if (horizontal(points[0]!, points[1]!)) p[1]!.y += dS;
			else if (horizontal(points[1]!, points[2]!)) p[1]!.y += dT;
		}
		return p;
	}

	// ── Compose absolute coordinates ───────────────────────────────────────────
	const placed: PlacedNode<T>[] = [];
	for (const n of ungrouped) {
		const p = rootPos.get(n.id) ?? { x: 0, y: 0 };
		placed.push({ ...n, x: p.x, y: p.y });
	}
	const groups: GroupBox[] = [];
	for (const name of groupNames) {
		const gl = groupLayouts.get(name)!;
		const origin = rootPos.get(groupIdOf(name)) ?? { x: 0, y: 0 };
		groups.push({
			id: groupIdOf(name),
			label: name,
			x: origin.x,
			y: origin.y,
			width: gl.size.width,
			height: gl.size.height,
		});
		for (const m of membersByGroup.get(name)!) {
			const rel = gl.children.get(m.id) ?? { x: 0, y: 0 };
			placed.push({ ...m, x: origin.x + rel.x, y: origin.y + rel.y });
		}
	}

	const rendered: RenderedEdge[] = [];
	// Internal group edges, offset to absolute space.
	for (const name of groupNames) {
		const gl = groupLayouts.get(name)!;
		const origin = rootPos.get(groupIdOf(name)) ?? { x: 0, y: 0 };
		for (const ge of gl.edges) {
			const orig = edges[ge.origIndex]!;
			rendered.push({
				from: orig.from,
				to: orig.to,
				label: orig.label,
				orig: [ge.origIndex],
				points: ge.points.map((p) => ({
					x: p.x + origin.x,
					y: p.y + origin.y,
				})),
				labelPos: ge.labelPos
					? { x: ge.labelPos.x + origin.x, y: ge.labelPos.y + origin.y }
					: undefined,
			});
		}
	}
	// Root edges (already absolute — flat root graph), endpoints snapped along
	// with their nodes.
	const rootEdgeList = [...rootEdges.values()];
	(rootRes.edges ?? []).forEach((el, i) => {
		const spec = rootEdgeList[i]!;
		const sec = el.sections?.[0];
		const points = sec
			? [sec.startPoint, ...(sec.bendPoints ?? []), sec.endPoint]
			: [];
		const lbl = el.labels?.[0];
		// A mid-route label follows its edge's snapped endpoints (mean delta).
		const labelDy =
			((rowDelta.get(spec.from) ?? 0) + (rowDelta.get(spec.to) ?? 0)) / 2;
		rendered.push({
			from: spec.from,
			to: spec.to,
			label: spec.label,
			orig: spec.orig,
			points: snapEdgePoints(points, spec.from, spec.to),
			labelPos:
				lbl && lbl.x != null && lbl.y != null
					? {
							x: lbl.x + (lbl.width ?? 0) / 2,
							y: lbl.y + (lbl.height ?? 0) / 2 + labelDy,
						}
					: undefined,
		});
	});

	// ── Empty-band squeeze ──────────────────────────────────────────────────────
	// Even after compaction, routing constraints can leave big voids between
	// layers/rows. Any interior band (horizontal or vertical) that contains no
	// nodes, groups, labels, or parallel edge runs is compressed to BAND_KEEP.
	// The remap is piecewise-linear and monotonic per axis — equal coordinates
	// stay equal, so orthogonal routes stay orthogonal and nothing can overlap
	// that didn't before.
	{
		const xOcc: Interval[] = [];
		const yOcc: Interval[] = [];
		for (const n of placed) {
			xOcc.push([n.x, n.x + n.width]);
			yOcc.push([n.y, n.y + n.height]);
		}
		for (const g of groups) {
			xOcc.push([g.x, g.x + g.width]);
			yOcc.push([g.y, g.y + g.height]);
		}
		for (const e of rendered) {
			if (e.label && e.labelPos) {
				const dims = labelDims(e.label);
				xOcc.push([
					e.labelPos.x - dims.width / 2,
					e.labelPos.x + dims.width / 2,
				]);
				yOcc.push([
					e.labelPos.y - dims.height / 2,
					e.labelPos.y + dims.height / 2,
				]);
			}
			// A run keeps a small halo so parallel runs in a squeezed channel don't
			// collapse onto each other. Runs PERPENDICULAR to the squeeze axis are
			// exactly what we want to shorten, so they don't count as occupied.
			for (let i = 0; i < e.points.length - 1; i++) {
				const a = e.points[i]!;
				const b = e.points[i + 1]!;
				if (Math.abs(a.y - b.y) < 0.5) yOcc.push([a.y - 7, a.y + 7]);
				if (Math.abs(a.x - b.x) < 0.5) xOcc.push([a.x - 7, a.x + 7]);
			}
		}
		const fx = buildBandRemap(xOcc);
		const fy = buildBandRemap(yOcc);
		for (const n of placed) {
			n.x = fx(n.x);
			n.y = fy(n.y);
		}
		for (const g of groups) {
			g.x = fx(g.x);
			g.y = fy(g.y);
		}
		for (const e of rendered) {
			for (const p of e.points) {
				p.x = fx(p.x);
				p.y = fy(p.y);
			}
			if (e.labelPos) {
				e.labelPos.x = fx(e.labelPos.x);
				e.labelPos.y = fy(e.labelPos.y);
			}
		}
	}

	let maxX = 0;
	let maxY = 0;
	for (const n of placed) {
		maxX = Math.max(maxX, n.x + n.width);
		maxY = Math.max(maxY, n.y + n.height);
	}
	for (const g of groups) {
		maxX = Math.max(maxX, g.x + g.width);
		maxY = Math.max(maxY, g.y + g.height);
	}

	return {
		nodes: placed,
		groups,
		edges: rendered,
		width: maxX + 16,
		height: maxY + 16,
	};
}

type Interval = [number, number];

/** How much of an empty band survives the squeeze. Matches the tightest
 *  between-layer spacing so squeezed voids read like normal gaps. */
const BAND_KEEP = 72;

/**
 * Build a monotonic piecewise-linear remap that compresses every gap between
 * occupied intervals down to BAND_KEEP. Positions inside a squeezed gap map
 * proportionally; positions past it shift by the accumulated savings.
 */
function buildBandRemap(occupied: Interval[]): (v: number) => number {
	const sorted = occupied.filter(([a, b]) => b > a).sort((a, b) => a[0] - b[0]);
	const merged: Interval[] = [];
	for (const iv of sorted) {
		const last = merged[merged.length - 1];
		if (last && iv[0] <= last[1]) last[1] = Math.max(last[1], iv[1]);
		else merged.push([iv[0], iv[1]]);
	}
	const cuts: { start: number; end: number }[] = [];
	for (let i = 0; i < merged.length - 1; i++) {
		const start = merged[i]![1];
		const end = merged[i + 1]![0];
		if (end - start > BAND_KEEP + 8) cuts.push({ start, end });
	}
	if (cuts.length === 0) return (v) => v;
	return (v) => {
		let out = v;
		for (const c of cuts) {
			const len = c.end - c.start;
			if (v >= c.end) out -= len - BAND_KEEP;
			else if (v > c.start) out -= (v - c.start) * (1 - BAND_KEEP / len);
		}
		return out;
	};
}

/**
 * A small arrowhead "V" path at the target end of a polyline. Drawn as a plain
 * path (rather than an SVG <marker>) so its stroke inherits the edge styling
 * directly and renders consistently.
 */
export function arrowHead(points: { x: number; y: number }[], len = 7): string {
	if (points.length < 2) return "";
	const p = points[points.length - 1]!;
	const q = points[points.length - 2]!;
	const ang = Math.atan2(p.y - q.y, p.x - q.x);
	const spread = 0.46;
	const a1x = p.x - len * Math.cos(ang - spread);
	const a1y = p.y - len * Math.sin(ang - spread);
	const a2x = p.x - len * Math.cos(ang + spread);
	const a2y = p.y - len * Math.sin(ang + spread);
	return `M ${a1x} ${a1y} L ${p.x} ${p.y} L ${a2x} ${a2y}`;
}

/**
 * Where to hang an edge label: the midpoint of the polyline's LONGEST segment.
 * Orthogonal routes bend right at node borders, so the naive "middle point of
 * the array" lands labels on top of nodes; the longest segment is the open
 * channel run where a label has room.
 */
export function labelAnchor(points: { x: number; y: number }[]): {
	x: number;
	y: number;
} | null {
	if (points.length === 0) return null;
	if (points.length === 1) return points[0]!;
	let best = 0;
	let bestLen = -1;
	for (let i = 0; i < points.length - 1; i++) {
		const len = Math.hypot(
			points[i + 1]!.x - points[i]!.x,
			points[i + 1]!.y - points[i]!.y,
		);
		if (len > bestLen) {
			bestLen = len;
			best = i;
		}
	}
	return {
		x: (points[best]!.x + points[best + 1]!.x) / 2,
		y: (points[best]!.y + points[best + 1]!.y) / 2,
	};
}

/** Orthogonal polyline → SVG path with rounded corners. The generous default
 *  radius turns right angles into soft S-curves; it self-clamps to half of
 *  each adjoining segment, so short zig-zags degrade gracefully. */
export function edgePath(points: { x: number; y: number }[], r = 56): string {
	if (points.length === 0) return "";
	if (points.length < 3) {
		return points
			.map((p, i) => `${i === 0 ? "M" : "L"} ${p.x} ${p.y}`)
			.join(" ");
	}
	const dist = (a: { x: number; y: number }, b: { x: number; y: number }) =>
		Math.hypot(b.x - a.x, b.y - a.y);
	const toward = (
		from: { x: number; y: number },
		to: { x: number; y: number },
		d: number,
	) => {
		const len = dist(from, to) || 1;
		return {
			x: from.x + ((to.x - from.x) / len) * d,
			y: from.y + ((to.y - from.y) / len) * d,
		};
	};

	let d = `M ${points[0]!.x} ${points[0]!.y}`;
	for (let i = 1; i < points.length - 1; i++) {
		const prev = points[i - 1]!;
		const p = points[i]!;
		const next = points[i + 1]!;
		const r1 = Math.min(r, dist(prev, p) / 2);
		const r2 = Math.min(r, dist(p, next) / 2);
		const a = toward(p, prev, r1);
		const b = toward(p, next, r2);
		d += ` L ${a.x} ${a.y} Q ${p.x} ${p.y} ${b.x} ${b.y}`;
	}
	const last = points[points.length - 1]!;
	d += ` L ${last.x} ${last.y}`;
	return d;
}

/* Derived for the Foglamp Design System portal by the project contributors.
 * It adapts Foglamp concepts and assets; this new integration code is not represented as upstream-authored.
 * Original project: Gustavo Fior (@gustavo-fior), Abdul Haidar, Foglamp Labs; Apache-2.0 source project.
 */
import { z } from "zod";

/** Max label length for graph nodes — keeps node cards a predictable width. */
export const MAX_NODE_LABEL = 28;

/**
 * The kinds of things that appear in a codebase's AI flow map. Each maps to a
 * fixed color + glyph in the renderer — the agent only tags, never styles.
 *
 *  - entry:    an entry point / trigger (route, webhook, page, command)
 *  - cron:     a scheduled / recurring job
 *  - agent:    an agent or named generateText/streamText flow
 *  - model:    an LLM (tag `domain` with the provider, e.g. "anthropic.com")
 *  - tool:     a tool/function the model can call (Exa, Firecrawl, a DB query…)
 *  - service:  an internal business-logic module/pipeline (billing, ingestion,
 *              a queue worker, a domain service) — code the project owns
 *  - store:    a datastore (Postgres, ClickHouse, Redis, a vector index…)
 *  - external: a third-party service/API the flow talks to
 */
export const NodeKind = z.enum([
  "entry",
  "cron",
  "agent",
  "model",
  "tool",
  "service",
  "store",
  "external",
]);
export type NodeKind = z.infer<typeof NodeKind>;

/**
 * Optional edge semantics — what the connection *does*. Rendered quietly:
 * revealed when the viewer traces a flow, unlike an explicit `label` which is
 * always visible.
 */
export const EdgeKind = z.enum(["calls", "reads", "writes", "triggers"]);
export type EdgeKind = z.infer<typeof EdgeKind>;

/** A logo-bearing item in the left rail (a model, tool, or integration). */
const RailItem = z.object({
  /** Stable id, lowercase-kebab (e.g. "gpt-4o", "exa"). */
  id: z.string().min(1).max(64),
  /** Human label shown on the chip (e.g. "GPT-4o", "Exa"). */
  label: z.string().min(1).max(40),
  /** Favicon domain for the logo (e.g. "openai.com"). Omit for a glyph fallback. */
  domain: z.string().min(1).max(120).optional(),
});
export type RailItem = z.infer<typeof RailItem>;

const GraphNode = z.object({
  /** Unique within the graph; referenced by edges. */
  id: z.string().min(1).max(64),
  label: z.string().min(1).max(MAX_NODE_LABEL),
  kind: NodeKind,
  /** Favicon domain for a logo on the node (mostly for model/tool/external). */
  domain: z.string().min(1).max(120).optional(),
  /** One short clarifying line (e.g. a model name under an agent). */
  sub: z.string().max(40).optional(),
  /** Longer context shown on click (e.g. file path, schedule, what it does). */
  detail: z.string().max(200).optional(),
  /** Pipeline stage this node belongs to (e.g. "Setup pipeline"). Nodes sharing
   *  a group render as one labeled vertical stack. */
  group: z.string().min(1).max(24).optional(),
  /** Where this lives in the repo (e.g. "src/agents/support.ts:42"). */
  sourceRef: z.string().min(1).max(120).optional(),
});
export type GraphNode = z.infer<typeof GraphNode>;

const GraphEdge = z.object({
  from: z.string().min(1).max(64),
  to: z.string().min(1).max(64),
  /** Optional short edge label (e.g. "on alert", "retry"). */
  label: z.string().max(24).optional(),
  /** Optional edge semantics; used as the label when `label` is omitted. */
  kind: EdgeKind.optional(),
});
export type GraphEdge = z.infer<typeof GraphEdge>;

export const ScanData = z
  .object({
    /** Schema version so the renderer can evolve without breaking old files. */
    version: z.literal(1),

    project: z.object({
      name: z.string().min(1).max(48),
      /** url-safe slug used in the footer (e.g. "foglamp"). */
      slug: z
        .string()
        .min(1)
        .max(48)
        .regex(/^[a-z0-9-]+$/, "slug must be lowercase letters, numbers, and dashes"),
      /** One-line description of the project. */
      tagline: z.string().max(80).optional(),
      /** Favicon domain for the project icon (e.g. the project's site). */
      iconDomain: z.string().max(120).optional(),
      /** ISO date (YYYY-MM-DD) the scan was generated. */
      date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, "date must be YYYY-MM-DD"),
    }),

    /** Headline counts for the left-rail stat grid. */
    stats: z.object({
      agents: z.number().int().min(0).max(9999),
      models: z.number().int().min(0).max(9999),
      tools: z.number().int().min(0).max(9999),
      integrations: z.number().int().min(0).max(9999),
    }),

    /** The most-used models, ranked. Max 3 so the rail list stays tidy. */
    topModels: z.array(RailItem).max(3).default([]),
    /** The most-used tools. Max 10 — the rail scrolls. */
    topTools: z.array(RailItem).max(10).default([]),
    /** Third-party integrations. Max 10 — the rail scrolls. */
    topIntegrations: z.array(RailItem).max(10).default([]),

    /** The flow map — one big map, business logic included. Caps exist only
     *  to bound pathological payloads; big maps are welcome (the viewer pans). */
    graph: z
      .object({
        nodes: z.array(GraphNode).min(1).max(60),
        edges: z.array(GraphEdge).max(120).default([]),
      })
      .refine(
        (g) => {
          const ids = new Set(g.nodes.map((n) => n.id));
          return g.edges.every((e) => ids.has(e.from) && ids.has(e.to));
        },
        { message: "every edge must reference existing node ids" },
      )
      .refine((g) => new Set(g.nodes.map((n) => n.id)).size === g.nodes.length, {
        message: "node ids must be unique",
      }),
  })
  .strict();

export type ScanData = z.infer<typeof ScanData>;

export interface ValidateOk {
  ok: true;
  data: ScanData;
}
export interface ValidateErr {
  ok: false;
  /** Human-readable lines like `topModels: array must contain at most 3 element(s)`. */
  errors: string[];
}

/**
 * Validate an unknown value (typically `JSON.parse` of an uploaded scan)
 * against the contract. Returns either the parsed, typed data or a flat list of
 * friendly error strings.
 */
export function validateScan(input: unknown): ValidateOk | ValidateErr {
  const res = ScanData.safeParse(input);
  if (res.success) return { ok: true, data: res.data };
  const errors = res.error.issues.map((issue) => {
    const path = issue.path.join(".") || "(root)";
    return `${path}: ${issue.message}`;
  });
  return { ok: false, errors };
}

